    });
    socket.on('disconnect', () => {
      console.log(`[Worker ${process.pid}] 🔴 Agente Local desconectado`);
    });
  });
  server.listen(app.get('port'), () => {
    console.log(`[Worker] PID ${process.pid} escuchando en el puerto ${app.get('port')}`);
  });
}
